import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

const DEFAULT_DATA_PATH = path.resolve(process.cwd(), 'books.json');

export class BookStorage {
  constructor(filePath = process.env.DATA_FILE || DEFAULT_DATA_PATH) {
    this.filePath = filePath;
  }

  async _readData() {
    try {
      const content = await fs.readFile(this.filePath, 'utf-8');
      const data = JSON.parse(content);
      return Array.isArray(data) ? data : [];
    } catch (err) {
      if (err.code === 'ENOENT') {
        // Initialize file if it doesn't exist
        await this._writeData([]);
        return [];
      }
      throw err;
    }
  }

  async _writeData(data) {
    const dir = path.dirname(this.filePath);
    await fs.mkdir(dir, { recursive: true });
    // Write via temp file for atomic persistence
    const tempPath = `${this.filePath}.${crypto.randomUUID()}.tmp`;
    await fs.writeFile(tempPath, JSON.stringify(data, null, 2), 'utf-8');
    await fs.rename(tempPath, this.filePath);
  }

  async getAllBooks() {
    return await this._readData();
  }

  async getBooksByStatus() {
    const books = await this.getAllBooks();
    const currentlyReading = books.filter((b) => b.status === 'reading');
    const finished = books.filter((b) => b.status === 'finished');
    return { currentlyReading, finished, all: books };
  }

  async getBookById(id) {
    const books = await this.getAllBooks();
    return books.find((b) => String(b.id) === String(id)) || null;
  }

  async addBook({ title, author, notes = '', status = 'reading' }) {
    if (!title || !title.trim()) {
      throw new Error('Title is required');
    }
    if (!author || !author.trim()) {
      throw new Error('Author is required');
    }

    const books = await this.getAllBooks();
    const normalizedStatus = status === 'finished' ? 'finished' : 'reading';

    const newBook = {
      id: crypto.randomUUID(),
      title: title.trim(),
      author: author.trim(),
      notes: (notes || '').trim(),
      status: normalizedStatus,
      createdAt: new Date().toISOString(),
      finishedAt: normalizedStatus === 'finished' ? new Date().toISOString() : null,
    };

    books.push(newBook);
    await this._writeData(books);
    return newBook;
  }

  async markAsFinished(id) {
    const books = await this.getAllBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      return null;
    }

    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
    await this._writeData(books);
    return book;
  }

  async markAsReading(id) {
    const books = await this.getAllBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      return null;
    }

    book.status = 'reading';
    book.finishedAt = null;
    await this._writeData(books);
    return book;
  }

  async updateBook(id, { title, author, notes, status }) {
    const books = await this.getAllBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      return null;
    }

    if (title !== undefined) book.title = title.trim();
    if (author !== undefined) book.author = author.trim();
    if (notes !== undefined) book.notes = notes.trim();
    if (status !== undefined) {
      book.status = status === 'finished' ? 'finished' : 'reading';
      if (book.status === 'finished' && !book.finishedAt) {
        book.finishedAt = new Date().toISOString();
      } else if (book.status === 'reading') {
        book.finishedAt = null;
      }
    }

    await this._writeData(books);
    return book;
  }

  async deleteBook(id) {
    const books = await this.getAllBooks();
    const initialLen = books.length;
    const filtered = books.filter((b) => String(b.id) !== String(id));
    if (filtered.length !== initialLen) {
      await this._writeData(filtered);
      return true;
    }
    return false;
  }
}

export const defaultStorage = new BookStorage();

