    }

    label {
      display: block;
      font-size: 0.85rem;
      font-weight: 600;
      color: #374151;
      margin-bottom: 0.4rem;
    }

    .form-input, .form-textarea, .form-select {
      width: 100%;
      padding: 0.65rem 0.85rem;
      border: 1px solid #d1c8bb;
      border-radius: 6px;
      font-family: inherit;
      font-size: 0.925rem;
      background: #fff;
      color: var(--text-main);
      transition: border-color 0.15s ease, box-shadow 0.15s ease;
    }

    .form-input:focus, .form-textarea:focus, .form-select:focus {
      outline: none;
      border-color: #4b5563;
      box-shadow: 0 0 0 3px rgba(75, 85, 99, 0.12);
    }

    .form-textarea {
      min-height: 90px;
      resize: vertical;
    }

    /* Detail View */
    .detail-container {
      max-width: 760px;
      margin: 0 auto;
    }

    .back-link {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      color: var(--text-muted);
      text-decoration: none;
      font-size: 0.9rem;
      font-weight: 500;
      margin-bottom: 1.5rem;
      transition: color 0.15s ease;
    }

    .back-link:hover {
      color: var(--text-main);
    }

    .detail-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 2.5rem;
      box-shadow: var(--shadow-md);
    }

    .detail-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
