function renderBookCard(book) {
  const isReading = book.status === 'reading';
  const badgeClass = isReading ? 'status-reading' : 'status-finished';
  const badgeText = isReading ? 'Reading' : 'Finished';
  const notesSnippet = book.notes
    ? `<div class="book-card-notes">${escapeHtml(book.notes)}</div>`
    : '';

  const finishAction = isReading
    ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish" style="margin: 0;">
        <button type="submit" class="btn btn-success btn-sm finish-btn" title="Mark as finished">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.75l6 6 9-13.5" />
          </svg>
          Mark Finished
        </button>
       </form>`
    : `<span style="font-size: 0.8rem; color: var(--text-muted);">${formatDate(book.finishedAt)}</span>`;

  return `
    <div class="book-card" data-book-id="${escapeHtml(book.id)}">
      <div>
        <a href="/books/${escapeHtml(book.id)}" class="book-card-link">
          <h3 class="book-card-title">${escapeHtml(book.title)}</h3>
          <p class="book-card-author">by ${escapeHtml(book.author)}</p>
        </a>
        ${notesSnippet}
      </div>

      <div class="book-card-footer">
        <span class="status-badge ${badgeClass}">${badgeText}</span>
        <div style="display: flex; gap: 0.4rem; align-items: center;">
          <a href="/books/${escapeHtml(book.id)}" class="btn btn-secondary btn-sm" title="View details">Details &rarr;</a>
          ${finishAction}
        </div>
      </div>
    </div>
  `;
}

