      <h1 style="font-family: 'Lora', Georgia, serif; font-size: 2rem; margin-bottom: 0.75rem;">Book Not Found</h1>
      <p style="color: var(--text-muted); margin-bottom: 1.5rem;">The book you are looking for does not exist or may have been deleted.</p>
      <a href="/" class="btn btn-primary">Back to All Books</a>
    </div>
  `;
  return layout({ title: 'Book Not Found', content, currentPath: '/404' });
}

input.content:
function escapeHtml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatDate(isoString) {
  if (!isoString) return '';
  try {
    const d = new Date(isoString);
    return d.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return isoString;
  }
}

export function layout({ title, content, currentPath = '/' }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)} - Book Tracker</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;0,600;1,400&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f8f6f0;
      --card-bg: #ffffff;
      --text-main: #1f2937;
      --text-muted: #6b7280;
      --text-light: #9ca3af;
      --primary: #2d3748;
      --primary-hover: #1a202c;
      --accent: #b45309;
      --accent-light: #fef3c7;
      --accent-text: #92400e;
      --success: #15803d;
      --success-light: #dcfce7;
      --border: #e5e0d8;
      --border-focus: #3b82f6;
      --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
      --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
      --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
      --radius: 10px;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
      background-color: var(--bg);
      color: var(--text-main);
      line-height: 1.6;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    header {
      background: #ffffff;
      border-bottom: 1px solid var(--border);
      padding: 1.25rem 2rem;
      position: sticky;
      top: 0;
      z-index: 20;
    }

    .header-content {
      max-width: 1000px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      text-decoration: none;
      color: var(--text-main);
    }

    .logo-icon {
      width: 32px;
      height: 32px;
      fill: none;
      stroke: var(--primary);
      stroke-width: 2;
    }

    .logo h1 {
      font-family: 'Lora', Georgia, serif;
      font-size: 1.5rem;
      font-weight: 600;
      letter-spacing: -0.02em;
    }

    .header-actions {
      display: flex;
      gap: 1rem;
      align-items: center;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      padding: 0.55rem 1.1rem;
      font-size: 0.9rem;
      font-weight: 600;
      border-radius: 8px;
      text-decoration: none;
      cursor: pointer;
      transition: all 0.15s ease-in-out;
      border: 1px solid transparent;
      font-family: inherit;
    }

    .btn-primary {
      background-color: var(--primary);
      color: #ffffff;
    }
    .btn-primary:hover {
      background-color: var(--primary-hover);
      transform: translateY(-1px);
    }

    .btn-accent {
      background-color: var(--accent);
      color: #ffffff;
    }
    .btn-accent:hover {
      background-color: #9a3412;
      transform: translateY(-1px);
    }

    .btn-secondary {
      background-color: #ffffff;
      color: var(--text-main);
      border-color: var(--border);
    }
    .btn-secondary:hover {
      background-color: #f3f0e6;
      border-color: #d1c9bd;
    }

    .btn-success {
      background-color: var(--success);
      color: #ffffff;
    }
    .btn-success:hover {
      background-color: #166534;
    }

    .btn-sm {
      padding: 0.35rem 0.75rem;
      font-size: 0.825rem;
    }

    main {
      max-width: 1000px;
      margin: 2rem auto;
      padding: 0 1.5rem;
      width: 100%;
      flex: 1;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 1.25rem;
      padding-bottom: 0.5rem;
      border-bottom: 2px solid var(--border);
    }

    .section-title {
      font-family: 'Lora', Georgia, serif;
      font-size: 1.35rem;
      font-weight: 600;
      color: var(--text-main);
      display: flex;
      align-items: center;
      gap: 0.6rem;
    }

    .badge-count {
      font-family: 'Plus Jakarta Sans', sans-serif;
      font-size: 0.75rem;
      font-weight: 700;
      padding: 0.15rem 0.6rem;
      background: #e2ded5;
      color: #4a453e;
      border-radius: 999px;
    }

    .book-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 1.25rem;
      margin-bottom: 2.5rem;
    }

    .book-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1.25rem;
      box-shadow: var(--shadow-sm);
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
      position: relative;
    }

    .book-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
      border-color: #cfc7bc;
    }

    .book-card-link {
      text-decoration: none;
      color: inherit;
      display: block;
      margin-bottom: 0.75rem;
    }

    .book-card-title {
      font-family: 'Lora', Georgia, serif;
      font-size: 1.15rem;
      font-weight: 600;
      line-height: 1.35;
      margin-bottom: 0.25rem;
      color: var(--text-main);
    }

    .book-card-title:hover {
      color: var(--accent);
    }

    .book-card-author {
      font-size: 0.9rem;
      color: var(--text-muted);
      margin-bottom: 0.75rem;
      font-weight: 500;
    }

    .book-card-notes {
      font-size: 0.85rem;
      color: #4b5563;
      background: #faf8f5;
      padding: 0.6rem 0.8rem;
      border-radius: 6px;
      border-left: 3px solid #d4cdbf;
      margin-bottom: 1rem;
      white-space: pre-line;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
      font-style: italic;
    }

    .book-card-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-top: auto;
      padding-top: 0.75rem;
      border-top: 1px solid #f1ece4;
      gap: 0.5rem;
    }

    .status-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      font-size: 0.75rem;
      font-weight: 600;
      padding: 0.25rem 0.6rem;
      border-radius: 999px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .status-reading {
      background-color: var(--accent-light);
      color: var(--accent-text);
    }

    .status-finished {
      background-color: var(--success-light);
      color: var(--success);
    }

    .empty-state {
      background: #faf8f5;
      border: 2px dashed #dbd4c7;
      border-radius: var(--radius);
      padding: 2.5rem 1.5rem;
      text-align: center;
      color: var(--text-muted);
      margin-bottom: 2.5rem;
    }

    .empty-state-icon {
      width: 48px;
      height: 48px;
      margin: 0 auto 0.75rem;
      stroke: #a89f91;
    }

    .empty-state p {
      font-size: 0.95rem;
    }

    /* Form Card */
    .form-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1.75rem;
      box-shadow: var(--shadow-sm);
      margin-top: 1rem;
    }

    .form-title {
      font-family: 'Lora', Georgia, serif;
      font-size: 1.25rem;
      font-weight: 600;
      margin-bottom: 1.25rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .form-group {
      margin-bottom: 1.25rem;
    }

    .form-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }

    @media (max-width: 640px) {
      .form-row {
        grid-template-columns: 1fr;
      }
    }

    label {
      display: block;
      font-size: 0.85rem;
      font-weight: 600;
      color: #374151;
      margin-bottom: 0.4rem;
    }

    .form-input, .form-textarea, .form-select {
      width: 100%;
      padding: 0.65rem 0.85rem;
      border: 1px solid #d1c8bb;
      border-radius: 6px;
      font-family: inherit;
      font-size: 0.925rem;
      background: #fff;
      color: var(--text-main);
      transition: border-color 0.15s ease, box-shadow 0.15s ease;
    }

    .form-input:focus, .form-textarea:focus, .form-select:focus {
      outline: none;
      border-color: #4b5563;
      box-shadow: 0 0 0 3px rgba(75, 85, 99, 0.12);
    }

    .form-textarea {
      min-height: 90px;
      resize: vertical;
    }

    /* Detail View */
    .detail-container {
      max-width: 760px;
      margin: 0 auto;
    }

    .back-link {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      color: var(--text-muted);
      text-decoration: none;
      font-size: 0.9rem;
      font-weight: 500;
      margin-bottom: 1.5rem;
      transition: color 0.15s ease;
    }

    .back-link:hover {
      color: var(--text-main);
    }

    .detail-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 2.5rem;
      box-shadow: var(--shadow-md);
    }

    .detail-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 1.5rem;
      margin-bottom: 1.5rem;
      padding-bottom: 1.5rem;
      border-bottom: 1px solid var(--border);
    }

    .detail-title {
      font-family: 'Lora', Georgia, serif;
      font-size: 2.1rem;
      font-weight: 600;
      line-height: 1.25;
      color: var(--text-main);
      margin-bottom: 0.4rem;
    }

    .detail-author {
      font-size: 1.15rem;
      color: var(--text-muted);
      font-weight: 500;
    }

    .detail-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      margin-bottom: 2rem;
      font-size: 0.85rem;
      color: var(--text-muted);
    }

    .notes-section {
      background: #faf8f5;
      border: 1px solid #e9e3d8;
      border-radius: 8px;
      padding: 1.5rem;
      margin-bottom: 2rem;
    }

    .notes-heading {
      font-family: 'Lora', Georgia, serif;
      font-size: 1.1rem;
      font-weight: 600;
      margin-bottom: 0.75rem;
      color: #374151;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .notes-content {
      font-size: 0.975rem;
      line-height: 1.7;
      color: #1f2937;
      white-space: pre-wrap;
      word-break: break-word;
    }

    .notes-empty {
      color: var(--text-light);
      font-style: italic;
      font-size: 0.925rem;
    }

    .detail-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--border);
    }

    .action-group {
      display: flex;
      gap: 0.75rem;
      align-items: center;
    }

    .share-box {
      background: #f3f0e8;
      border-radius: 8px;
      padding: 1rem 1.25rem;
      margin-top: 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .share-info {
      font-size: 0.85rem;
      color: var(--text-muted);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .share-url {
      font-family: monospace;
      font-weight: 600;
      color: #2d3748;
    }

    /* Toast Notification */
    #toast {
      visibility: hidden;
      min-width: 260px;
      background-color: #1f2937;
      color: #fff;
      text-align: center;
      border-radius: 8px;
      padding: 12px 20px;
      position: fixed;
      z-index: 100;
      bottom: 30px;
      left: 50%;
      transform: translateX(-50%);
      font-size: 0.9rem;
      box-shadow: var(--shadow-lg);
      opacity: 0;
      transition: opacity 0.25s, visibility 0.25s, transform 0.25s;
    }

    #toast.show {
      visibility: visible;
      opacity: 1;
      transform: translateX(-50%) translateY(-5px);
    }

    footer {
      text-align: center;
      padding: 2rem;
      font-size: 0.85rem;
      color: var(--text-light);
      margin-top: auto;
    }
  </style>
</head>
<body>
  <header>
    <div class="header-content">
      <a href="/" class="logo">
        <svg class="logo-icon" viewBox="0 0 24 24" stroke="currentColor" fill="none">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
        </svg>
        <h1>Book Tracker</h1>
      </a>
      <div class="header-actions">
        ${currentPath !== '/' ? `<a href="/" class="btn btn-secondary btn-sm">All Books</a>` : ''}
        <a href="#add-book-section" class="btn btn-primary btn-sm">+ Add Book</a>
      </div>
    </div>
  </header>

  <main>
    ${content}
  </main>

  <div id="toast">Link copied to clipboard!</div>

  <footer>
    <p>Saved locally to <code>books.json</code> &bull; Open & simple reading tracker</p>
  </footer>

  <script>
    function copyLink(url) {
      const targetUrl = url || window.location.href;
      navigator.clipboard.writeText(targetUrl).then(() => {
        showToast('Link copied to clipboard!');
      }).catch(() => {
        const input = document.createElement('input');
        input.value = targetUrl;
        document.body.appendChild(input);
        input.select();
        document.execCommand('copy');
        document.body.removeChild(input);
        showToast('Link copied to clipboard!');
      });
    }

    function showToast(msg) {
      const toast = document.getElementById('toast');
      if (toast) {
        toast.textContent = msg || 'Done!';
        toast.classList.add('show');
        setTimeout(() => {
          toast.classList.remove('show');
        }, 2500);
      }
    }
  </script>
</body>
</html>`;
}

export function renderHome({ currentlyReading, finished }) {
  const readingCards = currentlyReading.length > 0
    ? `<div class="book-grid" id="reading-list">
        ${currentlyReading.map((book) => renderBookCard(book)).join('')}
       </div>`
    : `<div class="empty-state" id="reading-empty">
        <svg class="empty-state-icon" viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke="currentColor">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
        </svg>
        <p>No books currently being read.</p>
        <p style="font-size: 0.85rem; margin-top: 0.25rem;">Use the form below to start tracking a new read!</p>
       </div>`;

  const finishedCards = finished.length > 0
    ? `<div class="book-grid" id="finished-list">
        ${finished.map((book) => renderBookCard(book)).join('')}
       </div>`
    : `<div class="empty-state" id="finished-empty">
        <svg class="empty-state-icon" viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke="currentColor">
          <path stroke-linecap="round" stroke-linejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
        <p>No finished books yet.</p>
        <p style="font-size: 0.85rem; margin-top: 0.25rem;">Books you mark as finished will appear here.</p>
       </div>`;

  const content = `
    <!-- Currently Reading Section -->
    <section style="margin-bottom: 3rem;">
      <div class="section-header">
        <h2 class="section-title">
          Currently Reading
          <span class="badge-count" id="reading-count">${currentlyReading.length}</span>
        </h2>
      </div>
      ${readingCards}
    </section>

    <!-- Finished Section -->
    <section style="margin-bottom: 3rem;">
      <div class="section-header">
        <h2 class="section-title">
          Finished
          <span class="badge-count" id="finished-count">${finished.length}</span>
        </h2>
      </div>
      ${finishedCards}
    </section>

    <!-- Add Book Section -->
    <section id="add-book-section">
      <div class="form-card">
        <h3 class="form-title">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path stroke-linecap="round" stroke-linejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
          </svg>
          Add a New Book
        </h3>
        <form method="POST" action="/books" id="add-book-form">
          <div class="form-row">
            <div class="form-group">
              <label for="title">Title *</label>
              <input type="text" id="title" name="title" class="form-input" placeholder="e.g. The Great Gatsby" required>
            </div>
            <div class="form-group">
              <label for="author">Author *</label>
              <input type="text" id="author" name="author" class="form-input" placeholder="e.g. F. Scott Fitzgerald" required>
            </div>
          </div>

          <div class="form-group">
            <label for="status">Status</label>
            <select id="status" name="status" class="form-select">
              <option value="reading" selected>Currently Reading</option>
              <option value="finished">Finished</option>
            </select>
          </div>

          <div class="form-group">
            <label for="notes">Notes / Reflections</label>
            <textarea id="notes" name="notes" class="form-textarea" placeholder="Key takeaways, thoughts, quotes, or progress..."></textarea>
          </div>

          <div style="display: flex; justify-content: flex-end;">
            <button type="submit" class="btn btn-primary" id="submit-book-btn">Add Book</button>
          </div>
        </form>
      </div>
    </section>
  `;

  return layout({ title: 'My Books', content, currentPath: '/' });
}

function renderBookCard(book) {
  const isReading = book.status === 'reading';
  const badgeClass = isReading ? 'status-reading' : 'status-finished';
  const badgeText = isReading ? 'Reading' : 'Finished';
  const notesSnippet = book.notes
    ? `<div class="book-card-notes">${escapeHtml(book.notes)}</div>`
    : '';

  const finishAction = isReading
    ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish" style="margin: 0;">
        <button type="submit" class="btn btn-success btn-sm finish-btn" title="Mark as finished">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.75l6 6 9-13.5" />
          </svg>
          Mark Finished
        </button>
       </form>`
    : `<span style="font-size: 0.8rem; color: var(--text-muted);">${formatDate(book.finishedAt)}</span>`;

  return `
    <div class="book-card" data-book-id="${escapeHtml(book.id)}">
      <div>
        <a href="/books/${escapeHtml(book.id)}" class="book-card-link">
          <h3 class="book-card-title">${escapeHtml(book.title)}</h3>
          <p class="book-card-author">by ${escapeHtml(book.author)}</p>
        </a>
        ${notesSnippet}
      </div>

      <div class="book-card-footer">
        <span class="status-badge ${badgeClass}">${badgeText}</span>
        <div style="display: flex; gap: 0.4rem; align-items: center;">
          <a href="/books/${escapeHtml(book.id)}" class="btn btn-secondary btn-sm" title="View details">Details &rarr;</a>
          ${finishAction}
        </div>
      </div>
    </div>
  `;
}

export function renderBookDetail(book, host) {
  const isReading = book.status === 'reading';
  const badgeClass = isReading ? 'status-reading' : 'status-finished';
  const badgeText = isReading ? 'Currently Reading' : 'Finished';
  const shareUrl = host ? `${host}/books/${book.id}` : `/books/${book.id}`;

  const notesHtml = book.notes && book.notes.trim()
    ? `<div class="notes-content">${escapeHtml(book.notes)}</div>`
    : `<p class="notes-empty">No notes added yet for this book.</p>`;

  const finishAction = isReading
    ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish" style="margin: 0;">
        <button type="submit" class="btn btn-success" id="finish-btn">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.75l6 6 9-13.5" />
          </svg>
          Mark as Finished
        </button>
       </form>`
    : `<form method="POST" action="/books/${escapeHtml(book.id)}/reading" style="margin: 0;">
        <button type="submit" class="btn btn-secondary btn-sm" id="reopen-btn">
          Move back to Reading
        </button>
       </form>`;

  const content = `
    <div class="detail-container">
      <a href="/" class="back-link">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path stroke-linecap="round" stroke-linejoin="round" d="M10.5 19.5L3 12m0 0l7.5-7.5M3 12h18" />
        </svg>
        Back to all books
      </a>

      <article class="detail-card">
        <div class="detail-header">
          <div>
            <h1 class="detail-title" id="book-title">${escapeHtml(book.title)}</h1>
            <p class="detail-author" id="book-author">by ${escapeHtml(book.author)}</p>
          </div>
          <span class="status-badge ${badgeClass}" id="book-status">${badgeText}</span>
        </div>

        <div class="detail-meta">
          <span>Added: ${formatDate(book.createdAt)}</span>
          ${book.finishedAt ? `<span>&bull; Finished: ${formatDate(book.finishedAt)}</span>` : ''}
        </div>

        <section class="notes-section">
          <h2 class="notes-heading">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
