          <form method="POST" action="/books/${escapeHtml(book.id)}/delete" onsubmit="return confirm('Are you sure you want to remove this book?');" style="margin: 0;">
            <button type="submit" class="btn btn-secondary btn-sm" style="color: #b91c1c;" id="delete-btn">
