          <div style="display: flex; justify-content: flex-end;">
            <button type="submit" class="btn btn-primary" id="submit-book-btn">Add Book</button>
          </div>
        </form>
      </div>
    </section>
  `;

  return layout({ title: 'My Books', content, currentPath: '/' });
}

function renderBookCard(book) {
  const isReading = book.status === 'reading';
  const badgeClass = isReading ? 'status-reading' : 'status-finished';
  const badgeText = isReading ? 'Reading' : 'Finished';
