export const app = createApp();

import express from 'express';
import { defaultStorage } from './storage.js';
import { renderHome, renderBookDetail, renderNotFound } from './views.js';

export function createApp(storage = defaultStorage) {
  const app = express();

  app.use(express.urlencoded({ extended: true }));
  app.use(express.json());

  // Helper to check if client prefers JSON
  function wantsJson(req) {
    if (req.query.format === 'json') return true;
    const accept = req.headers.accept || '';
    return accept.includes('application/json') && !accept.includes('text/html');
  }

  // Home Route
  app.get('/', async (req, res, next) => {
    try {
      const { currentlyReading, finished, all } = await storage.getBooksByStatus();

      if (wantsJson(req)) {
        return res.json({ books: all, currentlyReading, finished });
      }

      const html = renderHome({ currentlyReading, finished });
      res.type('html').send(html);
    } catch (err) {
      next(err);
    }
  });

  // Single Book Route
  app.get('/books/:id', async (req, res, next) => {
    try {
      const book = await storage.getBookById(req.params.id);

      if (!book) {
        if (wantsJson(req)) {
          return res.status(404).json({ error: 'Book not found' });
        }
        return res.status(404).type('html').send(renderNotFound());
      }

      if (wantsJson(req)) {
        return res.json({ book });
      }

      const host = `${req.protocol}://${req.get('host')}`;
      const html = renderBookDetail(book, host);
      res.type('html').send(html);
    } catch (err) {
      next(err);
    }
  });

  // Create Book
  app.post('/books', async (req, res, next) => {
    try {
      const { title, author, notes, status } = req.body;
      if (!title || !title.trim() || !author || !author.trim()) {
        if (wantsJson(req) || req.is('json')) {
          return res.status(400).json({ error: 'Title and author are required' });
        }
        return res.status(400).send('Title and author are required');
      }

      const newBook = await storage.addBook({
        title,
        author,
        notes,
        status,
      });

      if (wantsJson(req) || req.is('json')) {
        return res.status(201).json({ book: newBook });
      }

      // Redirect to home page
      res.redirect('/');
    } catch (err) {
      next(err);
    }
  });

  // Mark Book as Finished
  app.post('/books/:id/finish', async (req, res, next) => {
    try {
      const book = await storage.markAsFinished(req.params.id);
      if (!book) {
        if (wantsJson(req) || req.is('json')) {
          return res.status(404).json({ error: 'Book not found' });
        }
        return res.status(404).type('html').send(renderNotFound());
      }

      if (wantsJson(req) || req.is('json')) {
        return res.json({ success: true, book });
      }

      const referer = req.headers.referer;
      if (referer && referer.includes(`/books/${req.params.id}`)) {
        return res.redirect(`/books/${req.params.id}`);
      }
      res.redirect('/');
    } catch (err) {
      next(err);
    }
  });

  // Mark Book as Reading
  app.post('/books/:id/reading', async (req, res, next) => {
    try {
      const book = await storage.markAsReading(req.params.id);
      if (!book) {
        if (wantsJson(req) || req.is('json')) {
          return res.status(404).json({ error: 'Book not found' });
        }
        return res.status(404).type('html').send(renderNotFound());
      }

      if (wantsJson(req) || req.is('json')) {
        return res.json({ success: true, book });
      }

      const referer = req.headers.referer;
      if (referer && referer.includes(`/books/${req.params.id}`)) {
        return res.redirect(`/books/${req.params.id}`);
      }
      res.redirect('/');
    } catch (err) {
      next(err);
    }
  });

  // Delete Book
  app.post('/books/:id/delete', async (req, res, next) => {
    try {
      const deleted = await storage.deleteBook(req.params.id);
      if (!deleted) {
        if (wantsJson(req) || req.is('json')) {
          return res.status(404).json({ error: 'Book not found' });
        }
        return res.status(404).type('html').send(renderNotFound());
      }

      if (wantsJson(req) || req.is('json')) {
        return res.json({ success: true });
      }

      res.redirect('/');
    } catch (err) {
      next(err);
    }
  });

  // API Endpoints
  app.get('/api/books', async (req, res, next) => {
    try {
      const { currentlyReading, finished, all } = await storage.getBooksByStatus();
      res.json({ books: all, currentlyReading, finished });
    } catch (err) {
      next(err);
    }
  });

  app.post('/api/books', async (req, res, next) => {
    try {
      const { title, author, notes, status } = req.body;
      if (!title || !title.trim() || !author || !author.trim()) {
        return res.status(400).json({ error: 'Title and author are required' });
      }
      const newBook = await storage.addBook({ title, author, notes, status });
      res.status(201).json({ book: newBook });
    } catch (err) {
      next(err);
    }
  });

  app.get('/api/books/:id', async (req, res, next) => {
    try {
      const book = await storage.getBookById(req.params.id);
      if (!book) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.json({ book });
    } catch (err) {
      next(err);
    }
  });

  app.patch('/api/books/:id', async (req, res, next) => {
    try {
      const book = await storage.updateBook(req.params.id, req.body);
      if (!book) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.json({ book });
    } catch (err) {
      next(err);
    }
  });

  app.post('/api/books/:id/finish', async (req, res, next) => {
    try {
      const book = await storage.markAsFinished(req.params.id);
      if (!book) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.json({ book });
    } catch (err) {
      next(err);
    }
  });

  app.delete('/api/books/:id', async (req, res, next) => {
    try {
      const deleted = await storage.deleteBook(req.params.id);
      if (!deleted) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.json({ success: true });
    } catch (err) {
      next(err);
    }
  });

  // 404 handler
  app.use((req, res) => {
    if (wantsJson(req) || req.is('json')) {
      return res.status(404).json({ error: 'Not found' });
    }
    res.status(404).type('html').send(renderNotFound());
  });

  // Error handler
  app.use((err, req, res, next) => {
    console.error(err);
    if (wantsJson(req) || req.is('json')) {
      return res.status(500).json({ error: 'Internal server error' });
    }
    res.status(500).send('Internal Server Error');
  });

  return app;
}

export const app = createApp();

