import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { BookStorage } from '../src/storage.js';
import { createApp } from '../src/app.js';

describe('Book Tracker Application', () => {
  let tempDir;
  let dataFilePath;
  let storage;
  let server;
  let baseUrl;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'book-tracker-test-'));
    dataFilePath = path.join(tempDir, 'books.json');
    storage = new BookStorage(dataFilePath);

    const app = createApp(storage);
    server = app.listen(0);
    const port = server.address().port;
    baseUrl = `http://localhost:${port}`;
  });

  afterEach(async () => {
    if (server) {
      await new Promise((resolve) => server.close(resolve));
    }
    await fs.rm(tempDir, { recursive: true, force: true });
  });

  describe('Storage', () => {
    it('initializes with empty list when file does not exist', async () => {
      const books = await storage.getAllBooks();
      expect(books).toEqual([]);
    });

    it('adds and retrieves a book', async () => {
      const book = await storage.addBook({
        title: 'Atomic Habits',
        author: 'James Clear',
        notes: 'Small changes lead to remarkable results.',
      });

      expect(book.id).toBeDefined();
      expect(book.title).toBe('Atomic Habits');
      expect(book.author).toBe('James Clear');
      expect(book.notes).toBe('Small changes lead to remarkable results.');
      expect(book.status).toBe('reading');
      expect(book.finishedAt).toBeNull();

      const found = await storage.getBookById(book.id);
      expect(found).toEqual(book);
    });

    it('marks a book as finished with timestamp', async () => {
      const book = await storage.addBook({
        title: 'Deep Work',
        author: 'Cal Newport',
      });
      expect(book.status).toBe('reading');

      const finished = await storage.markAsFinished(book.id);
      expect(finished.status).toBe('finished');
      expect(finished.finishedAt).toBeDefined();

      const { currentlyReading, finished: finishedList } = await storage.getBooksByStatus();
      expect(currentlyReading.length).toBe(0);
      expect(finishedList.length).toBe(1);
      expect(finishedList[0].title).toBe('Deep Work');
    });

    it('persists data to json file and survives storage re-instantiation (restart simulation)', async () => {
      await storage.addBook({
        title: 'Clean Code',
        author: 'Robert C. Martin',
        notes: 'Meaningful names and small functions.',
      });

      // Simulate app restart by creating a new storage instance pointing to same file
      const newStorage = new BookStorage(dataFilePath);
      const books = await newStorage.getAllBooks();
      expect(books.length).toBe(1);
      expect(books[0].title).toBe('Clean Code');
      expect(books[0].notes).toBe('Meaningful names and small functions.');
    });
  });

  describe('Web UI & Routes', () => {
    it('displays empty state and sections when no books exist', async () => {
      const res = await fetch(`${baseUrl}/`);
      expect(res.status).toBe(200);
      const text = await res.text();

      expect(text).toContain('Currently Reading');
      expect(text).toContain('Finished');
      expect(text).toContain('Add a New Book');
      expect(text).toContain('No books currently being read');
      expect(text).toContain('No finished books yet');
    });

    it('adds a book via form submission and displays in Currently Reading', async () => {
      const formParams = new URLSearchParams({
        title: 'The Hobbit',
        author: 'J.R.R. Tolkien',
        notes: 'In a hole in the ground there lived a hobbit.',
        status: 'reading',
      });

      const postRes = await fetch(`${baseUrl}/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formParams.toString(),
        redirect: 'manual',
      });

      expect(postRes.status).toBe(302);
      expect(postRes.headers.get('location')).toBe('/');

      // Check home page
      const homeRes = await fetch(`${baseUrl}/`);
      const homeText = await homeRes.text();
      expect(homeText).toContain('The Hobbit');
      expect(homeText).toContain('J.R.R. Tolkien');
      expect(homeText).toContain('In a hole in the ground there lived a hobbit.');
      expect(homeText).toContain('Mark Finished');
    });

    it('navigates to single book page to see title, author, and notes', async () => {
      const book = await storage.addBook({
        title: '1984',
        author: 'George Orwell',
        notes: 'War is peace. Freedom is slavery. Ignorance is strength.',
      });

      const res = await fetch(`${baseUrl}/books/${book.id}`);
      expect(res.status).toBe(200);
      const html = await res.text();

      expect(html).toContain('1984');
      expect(html).toContain('George Orwell');
      expect(html).toContain('War is peace. Freedom is slavery. Ignorance is strength.');
      expect(html).toContain('Currently Reading');
      expect(html).toContain(`books/${book.id}`);
      expect(html).toContain('Copy Link');
      expect(html).toContain('Back to all books');
    });

    it('marks a book as finished from web form', async () => {
      const book = await storage.addBook({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'A lone astronaut must save the earth.',
      });

      const finishRes = await fetch(`${baseUrl}/books/${book.id}/finish`, {
        method: 'POST',
        redirect: 'manual',
      });
      expect(finishRes.status).toBe(302);

      // Verify on home page that it is now in Finished
      const homeRes = await fetch(`${baseUrl}/`);
      const homeHtml = await homeRes.text();

      // Check storage state
      const { currentlyReading, finished } = await storage.getBooksByStatus();
      expect(currentlyReading.length).toBe(0);
      expect(finished.length).toBe(1);
      expect(finished[0].id).toBe(book.id);

      // Check detail page status
      const detailRes = await fetch(`${baseUrl}/books/${book.id}`);
      const detailHtml = await detailRes.text();
      expect(detailHtml).toContain('Finished');
    });

    it('returns 404 for non-existent book', async () => {
      const res = await fetch(`${baseUrl}/books/non-existent-id`);
      expect(res.status).toBe(404);
      const text = await res.text();
      expect(text).toContain('Book Not Found');
    });

    it('supports direct link to book view for sharing', async () => {
      const book = await storage.addBook({
        title: 'Sapiens',
        author: 'Yuval Noah Harari',
        notes: 'A brief history of humankind.',
      });

      // Someone opening the direct link:
      const shareUrl = `${baseUrl}/books/${book.id}`;
      const res = await fetch(shareUrl);
      expect(res.status).toBe(200);
      const html = await res.text();
      expect(html).toContain('Sapiens');
      expect(html).toContain('Yuval Noah Harari');
      expect(html).toContain('A brief history of humankind.');
    });
  });

  describe('JSON API & Content Negotiation', () => {
    it('creates and lists books via JSON API', async () => {
      const createRes = await fetch(`${baseUrl}/api/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: 'Dune',
          author: 'Frank Herbert',
          notes: 'Fear is the mind-killer.',
        }),
      });

      expect(createRes.status).toBe(201);
      const createData = await createRes.json();
      expect(createData.book.title).toBe('Dune');
      expect(createData.book.author).toBe('Frank Herbert');

      const listRes = await fetch(`${baseUrl}/api/books`);
      const listData = await listRes.json();
      expect(listData.books.length).toBe(1);
      expect(listData.currentlyReading.length).toBe(1);
      expect(listData.finished.length).toBe(0);

      // Mark finished via API
      const finishRes = await fetch(`${baseUrl}/api/books/${createData.book.id}/finish`, {
        method: 'POST',
      });
      expect(finishRes.status).toBe(200);
      const finishData = await finishRes.json();
      expect(finishData.book.status).toBe('finished');

      // Fetch single book JSON
      const singleRes = await fetch(`${baseUrl}/api/books/${createData.book.id}`);
      const singleData = await singleRes.json();
      expect(singleData.book.status).toBe('finished');
      expect(singleData.book.notes).toBe('Fear is the mind-killer.');
    });
  });
});

